  `district_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `density_score` float NOT NULL,
  `year` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hotspot_id`),
  KEY `province_code` (`province_code`),
  KEY `district_code` (`district_code`),
  CONSTRAINT `hotspots_ibfk_1` FOREIGN KEY (`province_code`) REFERENCES `provinces` (`province_code`),
  CONSTRAINT `hotspots_ibfk_2` FOREIGN KEY (`district_code`) REFERENCES `districts` (`district_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
